<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';require_once __DIR__ . '/../modules/community-groups.php';require_login();start_app_session();
if(empty($_SESSION['community_settings_csrf']))$_SESSION['community_settings_csrf']=bin2hex(random_bytes(32));$csrf=(string)$_SESSION['community_settings_csrf'];$error='';$flash='';
$groups=community_group_list_for_producer();$selected=(string)($_GET['group']??($_POST['group_id']??($groups[0]['id']??'')));$current=null;foreach($groups as $group)if($group['id']===$selected){$current=$group;break;}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada.');}
    try{community_group_update_settings($selected,$_POST);$flash='Configurações atualizadas.';$groups=community_group_list_for_producer();foreach($groups as $group)if($group['id']===$selected){$current=$group;break;}}catch(DomainException $e){$error=$e->getMessage();}
}
function cs_e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configurar grupos — AFFILIEY</title><link rel="stylesheet" href="/assets/css/app-theme.css?v=3"><link rel="stylesheet" href="/assets/css/brand.css?v=affiliey4"><link rel="stylesheet" href="/assets/css/workspace-premium.css?v=3"><link rel="stylesheet" href="/assets/css/profile-environments.css?v=3"><link rel="stylesheet" href="/assets/css/typography.css?v=1"></head><body class="app-shell"><header class="topbar"><a class="brand" href="dashboard.php"><img class="brand-logo" src="/brand/affiliey-logo-dark.png" alt="AFFILIEY"></a><nav class="main-nav"><?= app_workspace_navigation() ?></nav><div class="top-actions"><?= app_header_account_tools() ?><span><?= cs_e(current_user()['name']??'') ?></span><a href="login.php?logout=1">Sair</a></div></header><main class="profile-page"><div class="profile-heading"><div><span class="profile-eyebrow">AMBIENTE DO PRODUTOR</span><h1>Configurar grupos</h1><p>Controle o acesso, a participação e a capa de cada comunidade.</p></div></div><?php if($error): ?><p class="message error" role="alert"><?= cs_e($error) ?></p><?php endif; ?><?php if($flash): ?><p class="message success" role="status"><?= cs_e($flash) ?></p><?php endif; ?><?php if(!$groups): ?><section class="profile-empty"><h2>Nenhum grupo cadastrado</h2><p>Crie um grupo antes de configurar as opções.</p><a class="button primary" href="communities.php">Criar grupo</a></section><?php else: ?><section class="profile-panel"><form method="get" class="community-form"><label>Grupo<select name="group" onchange="this.form.submit()"><?php foreach($groups as $group): ?><option value="<?= cs_e($group['id']) ?>" <?= $selected===$group['id']?'selected':'' ?>><?= cs_e($group['name']) ?></option><?php endforeach; ?></select></label></form></section><?php if($current): ?><section class="profile-panel"><h2><?= cs_e($current['name']) ?></h2><form method="post" class="community-form"><input type="hidden" name="csrf" value="<?= cs_e($csrf) ?>"><input type="hidden" name="group_id" value="<?= cs_e($selected) ?>"><label>Status<select name="active"><option value="1" <?= (int)$current['active']===1?'selected':'' ?>>Ativo</option><option value="0" <?= (int)$current['active']===0?'selected':'' ?>>Pausado</option></select></label><label>Entrada de novos participantes<select name="join_policy"><option value="automatic" <?= $current['join_policy']==='automatic'?'selected':'' ?>>Automática pelo convite</option><option value="approval" <?= $current['join_policy']==='approval'?'selected':'' ?>>Requer aprovação do produtor</option></select></label><label>Permitir saída do grupo<select name="allow_member_leave"><option value="1" <?= (int)$current['allow_member_leave']===1?'selected':'' ?>>Sim</option><option value="0" <?= (int)$current['allow_member_leave']===0?'selected':'' ?>>Não</option></select></label><label>Imagem de capa (HTTPS)<input type="url" name="cover_url" value="<?= cs_e($current['cover_url']) ?>" placeholder="https://..."></label><button class="button primary" type="submit">Salvar configurações</button></form></section><?php endif; ?><?php endif; ?></main></body></html>
